# Common Errors rows not triggered elsewhere: missing annotator file, dmFilter thresholds, swish without inferential replicates.
setwd("F:/OpenScience/audits/bio-isoform-switching/run"); dir.create("work", showWarnings = FALSE); setwd("work"); source("../helpers.R"); source("../helpers2.R")
suppressPackageStartupMessages({ library(IsoformSwitchAnalyzeR); library(DRIMSeq); library(tximeta); library(fishpond); library(SummarizedExperiment) }); set.seed(65)
msg <- function(expr) tryCatch({ force(expr); "NO ERROR" }, error = function(e) trimws(gsub("\n", " ", conditionMessage(e))))
ids <- c(sprintf("ctrl_%d", 1:3), sprintf("trt_%d", 1:3)); stage_salmon("w65", ids, sprintf("SRR76%05d", 1:6), rep(c("control", "treatment"), each = 3)); setwd("w65")
run_block("r_01.R"); sl <- suppressWarnings(analyzeORF(aSwitchList, orfMethod = "longest", genomeObject = NULL, quiet = TRUE))
m1 <- msg(analyzeSignalP(sl, pathToSignalPresultFile = "nope/signalp.txt")); cat("analyzeSignalP(missing file) ->", m1, "\n")
chk("missing SignalP file: 'The file(s) ... does not exist'", grepl("does not exist", m1))
m2 <- msg(analyzeIUPred2A(sl, pathToIUPred2AresultFile = "nope/iupred.txt")); cat("analyzeIUPred2A(missing file) ->", m2, "\n")
chk("missing IUPred2A file: 'does not exist'", grepl("does not exist", m2))
# dmFilter
txt <- readLines("../../blocks/r_04.R"); cat("dmFilter lines in block:", sum(grepl("dmFilter", txt)), "\n")
cts <- as.data.frame(sapply(1:6, function(j) rpois(30, 50))); colnames(cts) <- paste0("s", 1:6)
dd <- dmDSdata(counts = data.frame(gene_id = rep(paste0("G", 1:10), each = 3), feature_id = paste0("T", 1:30), cts), samples = data.frame(sample_id = colnames(cts), condition = factor(rep(c("a", "b"), each = 3))))
m3 <- msg(dmFilter(dd, min_samps_gene_expr = 12, min_gene_expr = 10)); cat("dmFilter(min_samps_gene_expr = 12 on 6 samples) ->", m3, "\n")
chk("dmFilter with more required samples than exist: 'min_samps_gene_expr <= ncol(x@counts) is not TRUE'", grepl("min_samps_gene_expr <= ncol", m3))
m4 <- msg(dmFilter(dd, min_samps_gene_expr = 6, min_gene_expr = 1e9)); cat("dmFilter(min_samps_gene_expr = 6, min_gene_expr = 1e9) ->", m4, "\n")
chk("dmFilter impossible threshold: '!No genes left after filtering!'", grepl("No genes left after filtering", m4))
# swish without inferential replicates (plain Salmon quant, no Gibbs)
PD <- "F:/OpenScience/audit-envs/alternative-splicing/public-data"; sm <- c("ERR188383", "ERR188428", "ERR188454", "ERR204916")
cd <- data.frame(names = sm, files = file.path(PD, "rnasplice/salmon", sm, "quant.sf"), condition = factor(c("GBR", "GBR", "YRI", "YRI")))
m5 <- msg({ se <- tximeta(cd, skipMeta = TRUE); scaleInfReps(se) }); cat("scaleInfReps(no Gibbs) ->", m5, "\n")
chk("swish without infReps: 'there are no inferential replicates in the assays'", grepl("no inferential replicates", m5))
cat("DONE 65\n")
